package local.mediacenter.library
import org.json.*
import org.junit.Test
import org.junit.Assert.*
class MixSnapshotPlanTest {
 private fun recipe()=JSONObject().put("id","mix").put("name","Mix").put("sources",JSONArray().put("a").put("b")).put("genres",JSONArray()).put("artists",JSONArray()).put("count",10).put("familiarity","balanced").put("refresh","daily").put("seed",1)
 @Test fun currentPeriodAndRecipeRevisionsGateRefresh(){val d=MixSnapshotPlan.definition(recipe());val saved=JSONObject().put("fingerprint",d.fingerprint).put("period",1).put("rows",JSONArray());assertFalse(MixSnapshotPlan.due(saved,d,86400000));assertTrue(MixSnapshotPlan.due(saved,d,2*86400000));assertTrue(MixSnapshotPlan.due(saved,MixSnapshotPlan.definition(recipe().put("seed",2)),86400000));assertFalse(MixSnapshotPlan.due(null,MixSnapshotPlan.definition(recipe().put("refresh","manual")),86400000))}
 @Test fun failedRefreshBackoffDoesNotDestroyThePreviousMix(){val d=MixSnapshotPlan.definition(recipe());val saved=JSONObject().put("fingerprint",d.fingerprint).put("period",0).put("rows",JSONArray().put("old")).put("attemptFingerprint",d.fingerprint).put("retryAfter",86400000+900000);assertFalse(MixSnapshotPlan.due(saved,d,86400000));assertTrue(MixSnapshotPlan.due(saved,d,86400000+900000));assertEquals("old",saved.getJSONArray("rows").getString(0))}
 @Test fun outputWhitelistsMetadataAndKeepsSourceIdentity(){val d=MixSnapshotPlan.definition(recipe());val input=JSONArray().put(JSONObject().put("account","a").put("id","same").put("url","https://private/?token=secret").put("headers","Bearer secret").put("coverArt","https://private/?token=secret")).put(JSONObject().put("account","b").put("id","same"));val rows=MixSnapshotPlan.rows(input,d);assertEquals(2,rows.length());assertFalse(rows.toString().contains("secret"));assertFalse(rows.getJSONObject(0).has("url"));assertTrue(runCatching{MixSnapshotPlan.rows(JSONArray().put(input.getJSONObject(0)).put(input.getJSONObject(0)),d)}.isFailure)}
 @Test fun invalidSourcesCountsFiltersAndSchedulesFail(){for(raw in listOf(recipe().put("sources",JSONArray()),recipe().put("count",501),recipe().put("refresh","every-second"),recipe().put("yearFrom",2025).put("yearTo",2000)))assertTrue(runCatching{MixSnapshotPlan.definition(raw)}.isFailure);assertTrue(runCatching{MixSnapshotPlan.rows(JSONArray().put(JSONObject().put("account","unknown").put("id","one")),MixSnapshotPlan.definition(recipe()))}.isFailure)}
}
